 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # The solid full row/column is the wall.
    wall = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            wall = ('h', r, grid[r][0])
            break
    if wall is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                wall = ('v', c, vals[0])
                break
    axis, pos, wall_color = wall
    colors = {v for row in grid for v in row if v != bg and v != wall_color}
    color = next(iter(colors))
    coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    out = [[bg] * w for _ in range(h)]
    # Preserve the wall and translate the object toward it until adjacent.
    if axis == 'h':
        out[pos] = [wall_color] * w
        minr = min(r for r, c in coords)
        shift = pos + 1 - minr
        moved = [(r + shift, c) for r, c in coords]
        for r, c in moved:
            out[r][c] = color
        line = max(r for r, c in moved) + 1
        if line < h:
            out[line] = [8] * w
    else:
        for r in range(h):
            out[r][pos] = wall_color
        minc = min(c for r, c in coords)
        shift = pos + 1 - minc
        moved = [(r, c + shift) for r, c in coords]
        for r, c in moved:
            out[r][c] = color
        line = max(c for r, c in moved) + 1
        if line < w:
            for r in range(h):
                out[r][line] = 8
    return out
